// texture objects

namespace {
// resource descriptions of the texture objects, for cudaGetTextureObjectResourceDesc
std::unordered_map<cudaTextureObject_t, cudaResourceDesc> g_textureResources{};
// and their texture descriptions, for cudaGetTextureObjectTextureDesc
std::unordered_map<cudaTextureObject_t, cudaTextureDesc> g_textureDescs{};
}

struct cudaChannelFormatDesc cudaCreateChannelDesc(int x, int y, int z, int w, enum cudaChannelFormatKind f) {
    cudaChannelFormatDesc desc{};
    desc.x = x;
    desc.y = y;
    desc.z = z;
    desc.w = w;
    desc.f = f;
    return desc;
}

namespace {
/**
 * The LibreCUDA element format of a channel description read with the given mode
 */
cudaError_t textureFormat(const cudaChannelFormatDesc &desc, cudaTextureReadMode readMode, LibreCuTexFormat *pFormat,
                          uint32_t *pChannels, uint32_t *pBits) {
    const int bits[4] = {desc.x, desc.y, desc.z, desc.w};
    uint32_t channels = 0;
    while (channels < 4 && bits[channels] != 0) {
        channels++;
    }
    for (uint32_t c = 1; c < channels; c++) {
        if (bits[c] != bits[0]) {
            return recordError(cudaErrorInvalidChannelDescriptor);
        }
    }
    if (channels == 0 || channels == 3) {
        return recordError(cudaErrorInvalidChannelDescriptor);
    }
    const bool normalized = readMode == cudaReadModeNormalizedFloat && bits[0] <= 16;
    switch (desc.f) {
        case cudaChannelFormatKindFloat:
            *pFormat = LIBRECUDA_TEX_FORMAT_FLOAT;
            break;
        case cudaChannelFormatKindSigned:
            *pFormat = normalized ? LIBRECUDA_TEX_FORMAT_SNORM : LIBRECUDA_TEX_FORMAT_SINT;
            break;
        case cudaChannelFormatKindUnsigned:
            *pFormat = normalized ? LIBRECUDA_TEX_FORMAT_UNORM : LIBRECUDA_TEX_FORMAT_UINT;
            break;
        default:
            return recordError(cudaErrorInvalidChannelDescriptor);
    }
    *pChannels = channels;
    *pBits = static_cast<uint32_t>(bits[0]);
    return cudaSuccess;
}

/**
 * The sampler of a texture description (address modes, filtering, coordinates, border color)
 */
cudaError_t textureSampler(const cudaTextureDesc &tex, LibreCuTexSampler *pSampler) {
    LibreCuTexSampler sampler{};
    for (int axis = 0; axis < 3; axis++) {
        switch (tex.addressMode[axis]) {
            case cudaAddressModeWrap: sampler.addressMode[axis] = LIBRECUDA_TEX_ADDRESS_WRAP; break;
            case cudaAddressModeClamp: sampler.addressMode[axis] = LIBRECUDA_TEX_ADDRESS_CLAMP; break;
            case cudaAddressModeMirror: sampler.addressMode[axis] = LIBRECUDA_TEX_ADDRESS_MIRROR; break;
            case cudaAddressModeBorder: sampler.addressMode[axis] = LIBRECUDA_TEX_ADDRESS_BORDER; break;
            default: return recordError(cudaErrorInvalidValue);
        }
    }
    sampler.linearFilter = tex.filterMode == cudaFilterModeLinear;
    sampler.normalizedCoords = tex.normalizedCoords != 0;
    for (int c = 0; c < 4; c++) {
        sampler.borderColor[c] = tex.borderColor[c];
    }
    *pSampler = sampler;
    return cudaSuccess;
}
} // namespace

cudaError_t cudaCreateTextureObject(cudaTextureObject_t *pTexObject, const struct cudaResourceDesc *pResDesc,
                                    const struct cudaTextureDesc *pTexDesc, const struct cudaResourceViewDesc *) {
    API_LOCK();
    if (pTexObject == nullptr || pResDesc == nullptr || pTexDesc == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    LibreCuTexFormat format{};
    uint32_t channels{}, bits{};
    LibreCUtexObject texture{};
    switch (pResDesc->resType) {
        case cudaResourceTypeLinear: {
            // tex1Dfetch: no sampling
            const auto &linear = pResDesc->res.linear;
            RT_CHECK(textureFormat(linear.desc, pTexDesc->readMode, &format, &channels, &bits));
            LC_CHECK(libreCuTexObjectCreateLinear(&texture, linear.devPtr, linear.sizeInBytes, format, channels,
                                                  bits));
            break;
        }
        case cudaResourceTypePitch2D: {
            const auto &pitch2D = pResDesc->res.pitch2D;
            RT_CHECK(textureFormat(pitch2D.desc, pTexDesc->readMode, &format, &channels, &bits));
            LibreCuTexSampler sampler{};
            RT_CHECK(textureSampler(*pTexDesc, &sampler));
            if (pitch2D.width > UINT32_MAX || pitch2D.height > UINT32_MAX) {
                return recordError(cudaErrorInvalidValue);
            }
            LC_CHECK(libreCuTexObjectCreatePitch2D(&texture, pitch2D.devPtr, static_cast<uint32_t>(pitch2D.width),
                                                   static_cast<uint32_t>(pitch2D.height), pitch2D.pitchInBytes, format,
                                                   channels, bits, &sampler));
            break;
        }
        case cudaResourceTypeArray: {
            cudaArray *array = pResDesc->res.array.array;
            if (array == nullptr) {
                return recordError(cudaErrorInvalidResourceHandle);
            }
            RT_CHECK(textureFormat(array->desc, pTexDesc->readMode, &format, &channels, &bits));
            LibreCuTexSampler sampler{};
            RT_CHECK(textureSampler(*pTexDesc, &sampler));
            LC_CHECK(libreCuTexObjectCreateArray(&texture, array->array, format, &sampler));
            break;
        }
        default:
            // mipmapped arrays aren't supported yet
            return recordError(cudaErrorNotSupported);
    }
    *pTexObject = texture;
    g_textureResources[texture] = *pResDesc;
    g_textureDescs[texture] = *pTexDesc;
    return cudaSuccess;
}

cudaError_t cudaDestroyTextureObject(cudaTextureObject_t texObject) {
    API_LOCK();
    if (texObject == 0) {
        return cudaSuccess;
    }
    RT_CHECK(activateCurrentDevice());
    LC_CHECK(libreCuTexObjectDestroy(texObject));
    g_textureResources.erase(texObject);
    g_textureDescs.erase(texObject);
    return cudaSuccess;
}

cudaError_t cudaGetTextureObjectResourceDesc(struct cudaResourceDesc *pResDesc, cudaTextureObject_t texObject) {
    API_LOCK();
    auto it = g_textureResources.find(texObject);
    if (pResDesc == nullptr || it == g_textureResources.end()) {
        return recordError(cudaErrorInvalidValue);
    }
    *pResDesc = it->second;
    return cudaSuccess;
}

// ---------------------------------------------------------------------------------------------------------------------
// surface objects

namespace {
// resource descriptions of the surface objects, for cudaGetSurfaceObjectResourceDesc
std::unordered_map<cudaSurfaceObject_t, cudaResourceDesc> g_surfaceResources{};
}

cudaError_t cudaCreateSurfaceObject(cudaSurfaceObject_t *pSurfObject, const struct cudaResourceDesc *pResDesc) {
    API_LOCK();
    if (pSurfObject == nullptr || pResDesc == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    // arrays only (any array: like CUDA, cudaArraySurfaceLoadStore isn't checked)
    if (pResDesc->resType != cudaResourceTypeArray || pResDesc->res.array.array == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    cudaArray *array = pResDesc->res.array.array;
    RT_CHECK(activateDevice(array->device));
    LibreCUsurfObject surface{};
    LC_CHECK(libreCuSurfObjectCreate(&surface, array->array));
    *pSurfObject = surface;
    g_surfaceResources[surface] = *pResDesc;
    return cudaSuccess;
}

cudaError_t cudaDestroySurfaceObject(cudaSurfaceObject_t surfObject) {
    API_LOCK();
    if (surfObject == 0) {
        return cudaSuccess;
    }
    RT_CHECK(activateCurrentDevice());
    LC_CHECK(libreCuSurfObjectDestroy(surfObject));
    g_surfaceResources.erase(surfObject);
    return cudaSuccess;
}

cudaError_t cudaGetSurfaceObjectResourceDesc(struct cudaResourceDesc *pResDesc, cudaSurfaceObject_t surfObject) {
    API_LOCK();
    auto it = g_surfaceResources.find(surfObject);
    if (pResDesc == nullptr || it == g_surfaceResources.end()) {
        return recordError(cudaErrorInvalidValue);
    }
    *pResDesc = it->second;
    return cudaSuccess;
}

cudaError_t cudaGetTextureObjectTextureDesc(struct cudaTextureDesc *pTexDesc, cudaTextureObject_t texObject) {
    API_LOCK();
    auto it = g_textureDescs.find(texObject);
    if (pTexDesc == nullptr || it == g_textureDescs.end()) {
        return recordError(cudaErrorInvalidValue);
    }
    *pTexDesc = it->second;
    return cudaSuccess;
}

cudaError_t cudaFuncGetAttributes(struct cudaFuncAttributes *attr, const void *func) {
    API_LOCK();
    if (attr == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    LibreCUFunction function{};
    RT_CHECK(currentFunction(func, &function));
    functionAttributes(function, attr);
    return cudaSuccess;
}

cudaError_t cudaFuncSetAttribute(const void *func, enum cudaFuncAttribute attr, int value) {
    API_LOCK();
    LibreCUFunction function{};
    RT_CHECK(currentFunction(func, &function));
    switch (attr) {
        case cudaFuncAttributeMaxDynamicSharedMemorySize:
            LC_CHECK(libreCuFuncSetAttribute(function, CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, value));
            break;
        default:
            break;
    }
    return cudaSuccess;
}

cudaError_t cudaFuncSetCacheConfig(const void *, enum cudaFuncCache) {
    return cudaSuccess;
}

cudaError_t cudaFuncGetName(const char **name, const void *func) {
    API_LOCK();
    KernelRecord *kernel{};
    RT_CHECK(lookupKernel(func, &kernel));
    *name = kernel->name.c_str();
    return cudaSuccess;
}

cudaError_t cudaOccupancyMaxActiveBlocksPerMultiprocessorWithFlags(int *numBlocks, const void *func, int blockSize,
                                                                   size_t dynamicSMemSize, unsigned int) {
    API_LOCK();
    if (numBlocks == nullptr || blockSize <= 0) {
        return recordError(cudaErrorInvalidValue);
    }
    LibreCUFunction function{};
    RT_CHECK(currentFunction(func, &function));
    occupancyOf(function, t_device, blockSize, dynamicSMemSize, numBlocks);
    return cudaSuccess;
}

cudaError_t cudaOccupancyMaxActiveBlocksPerMultiprocessor(int *numBlocks, const void *func, int blockSize,
                                                          size_t dynamicSMemSize) {
    return cudaOccupancyMaxActiveBlocksPerMultiprocessorWithFlags(numBlocks, func, blockSize, dynamicSMemSize, 0);
}

cudaError_t cudaOccupancyMaxActiveClusters(int *numClusters, const void *func, const cudaLaunchConfig_t *config) {
    API_LOCK();
    if (numClusters == nullptr || config == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    const dim3 cluster = clusterDimsOf(func, config);
    const int cluster_size = static_cast<int>(cluster.x * cluster.y * cluster.z);
    if (cluster_size > LIBRECUDA_MAX_CLUSTER_SIZE) {
        return recordError(cudaErrorInvalidClusterSize);
    }
    int blocks_per_gpc{}, gpcs{};
    RT_CHECK(blocksPerGpc(func, config, &blocks_per_gpc, &gpcs));
    *numClusters = (blocks_per_gpc / cluster_size) * gpcs;
    return cudaSuccess;
}

cudaError_t cudaOccupancyMaxPotentialClusterSize(int *clusterSize, const void *func,
                                                 const cudaLaunchConfig_t *config) {
    API_LOCK();
    if (clusterSize == nullptr || config == nullptr) {
        return recordError(cudaErrorInvalidValue);
    }
    RT_CHECK(activateCurrentDevice());
    int blocks_per_gpc{}, gpcs{};
    RT_CHECK(blocksPerGpc(func, config, &blocks_per_gpc, &gpcs));
    *clusterSize = std::min(LIBRECUDA_MAX_CLUSTER_SIZE, blocks_per_gpc);
    return cudaSuccess;
}

cudaError_t cudaOccupancyAvailableDynamicSMemPerBlock(size_t *dynamicSmemSize, const void *func, int numBlocks,
                                                      int) {
    API_LOCK();
    LibreCUFunction function{};
    RT_CHECK(currentFunction(func, &function));
    int static_smem{}, optin{};
    libreCuFuncGetAttribute(&static_smem, CU_FUNC_ATTRIBUTE_SHARED_SIZE_BYTES, function);
    libreCuDeviceGetAttribute(&optin, CU_DEVICE_ATTRIBUTE_MAX_SHARED_MEMORY_PER_BLOCK_OPTIN,
                              g_devices[t_device].device);
    *dynamicSmemSize = std::max(0, optin / std::max(1, numBlocks) - static_smem);
    return cudaSuccess;
}

cudaError_t cudaGetFuncBySymbol(cudaFunction_t *functionPtr, const void *symbolPtr) {
    API_LOCK();
    LibreCUFunction function{};
    RT_CHECK(currentFunction(symbolPtr, &function));
    *functionPtr = reinterpret_cast<cudaFunction_t>(function);
    return cudaSuccess;
}
